class Observer {
public:
    virtual ~Observer() = default;
    virtual void update(const string& message) = 0;
};

class Subject {
    vector<Observer*> observers;
public:
    void attach(Observer* obs) { observers.push_back(obs); }
    void detach(Observer* obs) {
        erase(observers, obs);
    }
    void notify(const string& message) {
        for (auto* obs : observers) {
            obs->update(message);
        }
    }
};

class ConcreteObserver : public Observer {
    string name;
public:
    ConcreteObserver(string n) : name(move(n)) {}
    void update(const string& msg) override {
        cout << name << " received: " << msg << '\n';
    }
};

Subject subject;
ConcreteObserver a("A"), b("B");
subject.attach(&a);
subject.attach(&b);
subject.notify("Hello!");
// A received: Hello!
// B received: Hello!

class Strategy {
public:
    virtual ~Strategy() = default;
    virtual int execute(int a, int b) const = 0;
};

class AddStrategy : public Strategy {
public:
    int execute(int a, int b) const override { return a + b; }
};

class MultiplyStrategy : public Strategy {
public:
    int execute(int a, int b) const override { return a * b; }
};

class Context {
    unique_ptr<Strategy> strategy;
public:
    void setStrategy(unique_ptr<Strategy> s) { strategy = move(s); }
    int executeStrategy(int a, int b) const { return strategy->execute(a, b); }
};

Context ctx;
