const int N = 100005;
vector<int> adj[N];
int parent[N], depth[N], heavy[N], head[N], pos[N];
int curPos = 0;

// First DFS: find size and heavy child
int dfs(int u) {
    int size = 1, maxSize = 0;
    heavy[u] = -1;
    for (int v : adj[u]) {
        if (v == parent[u]) continue;
        parent[v] = u;
        depth[v] = depth[u] + 1;
        int sz = dfs(v);
        if (sz > maxSize) {
            maxSize = sz;
            heavy[u] = v;
        }
        size += sz;
    }
    return size;
}

// Second DFS: decompose heavy chains
void decompose(int u, int h) {
    head[u] = h;
    pos[u] = curPos++;
    if (heavy[u] != -1)
        decompose(heavy[u], h);
    for (int v : adj[u]) {
        if (v != parent[u] && v != heavy[u])
            decompose(v, v);
    }
}

// Query path between u and v using segment tree (base[pos])
int queryPath(int u, int v) {
    int res = 0;
    while (head[u] != head[v]) {
        if (depth[head[u]] < depth[head[v]]) swap(u, v);
        // Query segment [pos[head[u]], pos[u]]
        // res = max(res, segQuery(pos[head[u]], pos[u]));
        u = parent[head[u]];
    }
    if (depth[u] > depth[v]) swap(u, v);
    // Query segment [pos[u], pos[v]]
    // res = max(res, segQuery(pos[u], pos[v]));
    return res;
}

using Matrix = vector<vector<long long>>;

Matrix mul(const Matrix& a, const Matrix& b, long long mod) {
    int n = a.size();
    Matrix res(n, vector<long long>(n, 0));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            for (int k = 0; k < n; ++k)
                res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % mod;
    return res;
}

Matrix matrixPow(Matrix mat, long long exp, long long mod) {
    int n = mat.size();
    Matrix res(n, vector<long long>(n, 0));
    for (int i = 0; i < n; ++i) res[i][i] = 1;  // Identity

    while (exp > 0) {
        if (exp & 1) res = mul(res, mat, mod);
        mat = mul(mat, mat, mod);
        exp >>= 1;
    }
    return res;
}

// Fibonacci example: F(n) = F(n-1) + F(n-2)
// [F(n), F(n-1)]^T = [[1,1],[1,0]]^n * [F(1), F(0)]^T
long long fib(long long n, long long mod) {
    if (n == 0) return 0;
    Matrix base = {{1, 1}, {1, 0}};
    Matrix powered = matrixPow(base, n - 1, mod);
    return powered[0][0];  // F(n) assuming F(1)=1, F(0)=0
}

