// Method 2: string_view + find (no allocation per token)
vector<string_view> split_sv(string_view sv, char delim) {
    vector<string_view> tokens;
    size_t start = 0, end;
    while ((end = sv.find(delim, start)) != string_view::npos) {
        tokens.push_back(sv.substr(start, end - start));
        start = end + 1;
    }
    tokens.push_back(sv.substr(start));
    return tokens;
}

