const int N = 10000000;
vector<int> primes;
int spf[N + 1];  // smallest prime factor

void linearSieve() {
    for (int i = 2; i <= N; ++i) {
        if (spf[i] == 0) {
            spf[i] = i;
            primes.push_back(i);
        }
        for (int p : primes) {
            if (p > spf[i] || i * p > N) break;
            spf[i * p] = p;
        }
    }
}

// Factor any number in O(log n) using SPF:
auto factorize(int x) {
    vector<pair<int,int>> factors;  // {prime, exponent}
    while (x > 1) {
        int p = spf[x], cnt = 0;
        while (x % p == 0) {
            x /= p;
            cnt++;
        }
        factors.emplace_back(p, cnt);
    }
    return factors;
}
